<?php require '../includes/auth.php';require '../includes/header.php';$u=guard('admin',['hr_manager']);csrf_check();$a=$_POST['_action']??'';
if($a==='add'){db()->prepare("INSERT INTO announcements(title,body,priority,audience,is_pinned) VALUES(?,?,?,?,?)")->execute([trim($_POST['title']),trim($_POST['body']),$_POST['priority'],$_POST['audience'],isset($_POST['pin'])?1:0]);audit($u['id'],'Posted announcement');flash('Posted');redirect('announcements.php');}
if($a==='pin'||$a==='archive'){$c=$a==='pin'?'is_pinned':'archived';db()->prepare("UPDATE announcements SET $c=1-$c WHERE id=?")->execute([(int)$_POST['id']]);redirect('announcements.php');}
$rows=db()->query("SELECT * FROM announcements ORDER BY id DESC")->fetchAll();page_head('Announcements',[],$u);?>
<form method="post" class="card p-3 mb-4"><?=csrf_field()?><input type="hidden" name="_action" value="add"><input class="form-control mb-2" name="title" placeholder="Title" required><textarea class="form-control mb-2" name="body" rows="3" placeholder="Content" required></textarea>
<div class="d-flex gap-2 flex-wrap"><select class="form-select w-auto" name="priority"><option>Normal<option>Important<option>Urgent</select><select class="form-select w-auto" name="audience"><option value="employees">All Employees<option value="candidates">Candidates<option value="all">Everyone</select><label class="form-check align-self-center"><input type="checkbox" class="form-check-input" name="pin"> Pin</label><button class="btn btn-primary ms-auto">Publish</button></div></form>
<div class="card table-responsive"><table class="table mb-0"><tr><th>Title</th><th>Priority</th><th>Audience</th><th>State</th><th></th></tr><?php foreach($rows as $r){?><tr><td><?=e($r['title'])?></td><td><span class="badge text-bg-<?=badge($r['priority'])?>"><?=e($r['priority'])?></span></td><td><?=e($r['audience'])?></td><td><?=$r['archived']?'Archived':($r['is_pinned']?'Pinned':'Live')?></td>
<td class="d-flex gap-1"><?php foreach(['pin'=>'Pin','archive'=>'Archive'] as $k=>$l){?><form method="post"><?=csrf_field()?><input type="hidden" name="_action" value="<?=$k?>"><input type="hidden" name="id" value="<?=$r['id']?>"><button class="btn btn-sm btn-outline-secondary"><?=$l?></button></form><?php }?></td></tr><?php }?></table></div><?php page_foot();
